        s = sorted(str(n))
        return int(s[-1]) * int(s[-2])

#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxProduct(int n) {
        string s = to_string(n);
        sort(s.begin(), s.end());
        int sz = s.length();
        return (s[sz - 1] - '0') * (s[sz - 2] - '0');
    }
};

import java.util.*;

class Solution {
    public int maxProduct(int n) {
        char[] s = String.valueOf(n).toCharArray();
        Arrays.sort(s);
        int sz = s.length;
        return (s[sz - 1] - '0') * (s[sz - 2] - '0');
    }
}

var maxProduct = function(n) {
    const s = String(n).split("").sort();
    return Number(s[s.length - 1]) * Number(s[s.length - 2]);
};
